ext('c12_phy_ch10',[
C("🌊","समतल तरंगाग्र",["समान कला वाले बिंदुओं का तल","तरंगाग्र के लंबवत किरण","गोलीय और बेलनाकार","हाइगेन्स की रचना"],"किसी तरंग में समान कला वाले सभी बिंदुओं को जोड़ने वाली सतह को तरंगाग्र कहते हैं। बिंदु स्रोत से गोलीय तरंगाग्र निकलता है और बहुत दूर जाकर वह लगभग समतल हो जाता है। किरणें हमेशा तरंगाग्र के लंबवत होती हैं। हाइगेन्स के सिद्धांत से तरंगाग्र की अगली स्थिति निकाली जाती है।"),
C("🪞","हाइगेन्स से परावर्तन और अपवर्तन",["परावर्तन का नियम","अपवर्तन में गति बदलती","स्नेल का नियम","तरंगदैर्घ्य बदलती, आवृत्ति नहीं"],"हाइगेन्स के सिद्धांत से परावर्तन और अपवर्तन के नियम सिद्ध होते हैं। परावर्तन में आपतन कोण और परावर्तन कोण बराबर निकलते हैं। अपवर्तन में प्रकाश की चाल बदल जाती है, जिससे दिशा बदलती है और स्नेल का नियम मिलता है। अपवर्तन में तरंगदैर्घ्य बदलती है पर आवृत्ति वही रहती है।"),
C("⚪","एकल झिरी विवर्तन",["झिरी की चौड़ाई तरंगदैर्घ्य के बराबर","केंद्रीय चमकीला पट्ट","दोनों ओर कम चमकीली पट्टियाँ","चौड़ाई जितनी कम, पट्ट उतना चौड़ा"],"जब प्रकाश बहुत पतली झिरी से गुज़रता है, तो वह पर्दे पर सीधा नहीं फैलता, बल्कि एक चमकीला केंद्रीय पट्ट और उसके दोनों ओर कम चमकीले पट्ट बनाता है। इसे विवर्तन कहते हैं। झिरी जितनी पतली होती है, केंद्रीय पट्ट उतना ही चौड़ा बनता है।"),
C("💡","ध्रुवण के उपयोग",["पोलेरॉइड धूप के चश्मे","चमक कम करना","3D फ़िल्मों के चश्मे","प्रकाश अनुप्रस्थ तरंग"],"ध्रुवित प्रकाश में कंपन केवल एक ही तल में होते हैं। पोलेरॉइड चश्मे चमक कम करने के लिए इसका उपयोग करते हैं। थ्री डी फ़िल्मों के चश्मे भी ध्रुवण पर आधारित होते हैं। ध्रुवण से सिद्ध होता है कि प्रकाश अनुप्रस्थ तरंग है, क्योंकि अनुदैर्ध्य तरंगों का ध्रुवण नहीं होता।"),
],5)
ext('c12_phy_ch11',[
C("💡","देहली आवृत्ति",["न्यूनतम आवृत्ति","इससे कम पर कोई उत्सर्जन नहीं","चाहे तीव्रता कितनी भी हो","हर धातु की अलग"],"प्रकाश-विद्युत प्रभाव के लिए हर धातु की एक न्यूनतम आवृत्ति होती है जिसे देहली आवृत्ति कहते हैं। इससे कम आवृत्ति का प्रकाश चाहे कितना भी तीव्र क्यों न हो, इलेक्ट्रॉन बाहर नहीं निकलते। यह तरंग सिद्धांत से समझ में नहीं आता, पर आइंस्टीन के फ़ोटॉन सिद्धांत से आसानी से समझ में आता है।"),
C("⚛️","फ़ोटॉन की संकल्पना",["प्रकाश ऊर्जा के पैकेट","ऊर्जा = h × आवृत्ति","द्रव्यमान शून्य","चाल प्रकाश के बराबर"],"आइंस्टीन के अनुसार प्रकाश ऊर्जा के छोटे-छोटे पैकेटों के रूप में चलता है, जिन्हें फ़ोटॉन कहते हैं। हर फ़ोटॉन की ऊर्जा प्लांक स्थिरांक और आवृत्ति के गुणनफल के बराबर होती है। फ़ोटॉन का विराम द्रव्यमान शून्य होता है और वह हमेशा प्रकाश की चाल से चलता है।"),
C("🔋","प्रकाश-विद्युत सेल के उपयोग",["स्वचालित दरवाज़े","चोर अलार्म","प्रकाश-मापी","सौर पैनल"],"प्रकाश-विद्युत प्रभाव पर आधारित सेल कई जगह काम आते हैं। स्वचालित दरवाज़ों में प्रकाश कट जाने पर वे खुल जाते हैं। चोर अलार्म, प्रकाश-मापी और कैमरों में भी इनका उपयोग होता है। सौर पैनल भी इसी तरह के सिद्धांत पर प्रकाश से बिजली बनाते हैं।"),
C("🌊","द्रव्य तरंगों का अर्थ",["डी ब्रॉग्ली की परिकल्पना","कण में तरंग के गुण","तरंगदैर्घ्य = h भाग संवेग","इलेक्ट्रॉन विवर्तन का प्रमाण"],"डी ब्रॉग्ली ने कहा कि जिस प्रकार प्रकाश में कण और तरंग दोनों के गुण होते हैं, उसी प्रकार इलेक्ट्रॉन जैसे कणों में भी तरंग के गुण होते हैं। इन तरंगों की तरंगदैर्घ्य प्लांक स्थिरांक को संवेग से भाग देने पर मिलती है। डेविसन और जर्मर के प्रयोग ने इसकी पुष्टि की।"),
],5)
ext('c12_phy_ch12',[
C("🎯","रदरफ़ोर्ड का नाभिकीय मॉडल",["अधिकांश परमाणु खाली","धनावेश केंद्र में केंद्रित","इलेक्ट्रॉन चारों ओर घूमते","कुछ कण वापस लौटे"],"रदरफ़ोर्ड के प्रयोग में सोने की पतली पन्नी पर अल्फा कण छोड़े गए। अधिकांश कण सीधे निकल गए, पर कुछ बहुत बड़े कोण पर मुड़ गए और कुछ वापस लौट आए। इससे निष्कर्ष निकला कि परमाणु का अधिकांश भाग खाली है और उसका धनावेश और लगभग पूरा द्रव्यमान एक बहुत छोटे नाभिक में केंद्रित है।"),
C("🪐","बोर मॉडल की अभिधारणाएँ",["इलेक्ट्रॉन निश्चित कक्षाओं में","उन कक्षाओं में ऊर्जा विकिरण नहीं","कक्षा बदलने पर फ़ोटॉन","कोणीय संवेग क्वांटित"],"बोर ने कहा कि इलेक्ट्रॉन नाभिक के चारों ओर केवल कुछ निश्चित कक्षाओं में घूम सकते हैं और इन कक्षाओं में रहते हुए ऊर्जा विकिरित नहीं करते। जब इलेक्ट्रॉन एक कक्षा से दूसरी में जाता है, तो दोनों ऊर्जा स्तरों के अंतर के बराबर ऊर्जा का फ़ोटॉन उत्सर्जित या अवशोषित होता है।"),
C("🌈","हाइड्रोजन की स्पेक्ट्रल श्रेणियाँ",["लाइमैन: पराबैंगनी","बामर: दृश्य","पाशन: अवरक्त","ब्रैकेट और फुंड"],"हाइड्रोजन परमाणु के स्पेक्ट्रम में कई श्रेणियाँ मिलती हैं। इलेक्ट्रॉन जब ऊपरी स्तरों से पहले स्तर पर आता है, तो लाइमैन श्रेणी बनती है, जो पराबैंगनी में होती है। दूसरे स्तर पर आने से बामर श्रेणी बनती है, जो दृश्य प्रकाश में है। तीसरे स्तर पर आने से पाशन श्रेणी बनती है, जो अवरक्त में है।"),
C("⚡","आयनन ऊर्जा",["इलेक्ट्रॉन को बाहर निकालने की ऊर्जा","हाइड्रोजन के लिए तेरह दशमलव छह इलेक्ट्रॉन वोल्ट","भू-अवस्था से","ऊर्जा स्तर ऋणात्मक"],"किसी परमाणु के इलेक्ट्रॉन को उसकी निम्नतम ऊर्जा अवस्था से पूरी तरह बाहर निकालने के लिए जितनी ऊर्जा चाहिए, उसे आयनन ऊर्जा कहते हैं। हाइड्रोजन परमाणु के लिए यह तेरह दशमलव छह इलेक्ट्रॉन वोल्ट होती है। ऊर्जा स्तरों को ऋणात्मक लिखा जाता है, क्योंकि इलेक्ट्रॉन नाभिक से बँधा हुआ है।"),
],5)
ext('c12_phy_ch13',[
C("⚛️","नाभिक का आकार",["त्रिज्या A की एक तिहाई घात","घनत्व लगभग समान","बहुत छोटा आकार","फ़र्मी इकाई"],"नाभिक की त्रिज्या उसके द्रव्यमान संख्या के घनमूल के अनुपात में होती है। इससे पता चलता है कि सभी नाभिकों का घनत्व लगभग एक जैसा होता है, जो बहुत ज़्यादा है। नाभिक का आकार मापने के लिए फ़र्मी नाम की इकाई प्रयोग होती है, जो मीटर का दस की घात माइनस पंद्रह भाग होती है।"),
C("🧪","रेडियोधर्मी क्षय के प्रकार",["अल्फा क्षय: हीलियम नाभिक","बीटा क्षय: इलेक्ट्रॉन","गामा क्षय: ऊर्जा का फ़ोटॉन","पुत्री नाभिक बनता"],"रेडियोधर्मी क्षय तीन प्रकार का होता है। अल्फा क्षय में नाभिक से एक हीलियम नाभिक निकलता है। बीटा क्षय में इलेक्ट्रॉन या पॉज़िट्रॉन बाहर आता है। गामा क्षय में नाभिक उच्च ऊर्जा अवस्था से निम्न में आकर गामा फ़ोटॉन छोड़ता है। हर क्षय में नया नाभिक बनता है, जिसे पुत्री नाभिक कहते हैं।"),
C("⏳","अर्ध-आयु और औसत आयु",["अर्ध-आयु: आधा नाभिक क्षय","औसत आयु: अर्ध-आयु की लगभग डेढ़ गुनी","क्षय स्थिरांक","कार्बन डेटिंग में उपयोग"],"किसी रेडियोधर्मी पदार्थ के आधे नाभिकों के क्षय में लगने वाला समय उसकी अर्ध-आयु कहलाता है। औसत आयु अर्ध-आयु से लगभग डेढ़ गुनी होती है। इनका संबंध क्षय स्थिरांक से जुड़ा है। कार्बन-चौदह की अर्ध-आयु के आधार पर प्राचीन अवशेषों की आयु निकाली जाती है।"),
C("☢️","नाभिकीय रिएक्टर",["नियंत्रित विखंडन","मंदक: भारी जल","नियंत्रक छड़ें","ऊर्जा बिजली में बदलती"],"नाभिकीय रिएक्टर में यूरेनियम के नियंत्रित विखंडन से ऊर्जा बनाई जाती है। न्यूट्रॉनों की गति को कम करने के लिए मंदक के रूप में भारी जल या ग्रेफ़ाइट का उपयोग होता है। नियंत्रक छड़ें न्यूट्रॉनों को सोखकर विखंडन की दर नियंत्रित करती हैं। निकली ऊष्मा से भाप बनाकर बिजली बनाई जाती है।"),
],5)
ext('c12_phy_ch14',[
C("🔀","पी-एन संधि का निर्माण",["पी और एन क्षेत्र का मेल","विसरण","अवक्षय क्षेत्र","अवरोध विभव"],"जब पी प्रकार और एन प्रकार के अर्धचालक को जोड़ा जाता है, तो इलेक्ट्रॉन एन क्षेत्र से पी क्षेत्र की ओर और होल पी से एन की ओर विसरित होते हैं। संधि के पास एक क्षेत्र बन जाता है जिसमें मुक्त आवेश वाहक नहीं रहते, जिसे अवक्षय क्षेत्र कहते हैं। इससे एक अवरोध विभव पैदा होता है।"),
C("➡️","अग्र और पश्च अभिनति",["अग्र अभिनति: धारा बहती है","पश्च अभिनति: धारा लगभग शून्य","अवक्षय क्षेत्र घटता या बढ़ता","डायोड की एकदिश चालकता"],"जब पी क्षेत्र को बैटरी के धनात्मक सिरे और एन क्षेत्र को ऋणात्मक सिरे से जोड़ा जाए, तो यह अग्र अभिनति है और धारा आसानी से बहती है। उलटा जोड़ने पर पश्च अभिनति होती है और बहुत कम धारा बहती है। इसी कारण डायोड धारा को केवल एक दिशा में जाने देता है।"),
C("🔌","दिष्टकारी",["अर्ध-तरंग दिष्टकारी","पूर्ण-तरंग दिष्टकारी","ए.सी. को डी.सी. में बदलना","फ़िल्टर परिपथ से चिकना"],"प्रत्यावर्ती धारा को दिष्ट धारा में बदलने के लिए दिष्टकारी लगाया जाता है। अर्ध-तरंग दिष्टकारी में एक डायोड होता है और वह ए.सी. के आधे चक्र में ही धारा देता है। पूर्ण-तरंग दिष्टकारी में दो या चार डायोड लगते हैं और वह पूरे चक्र में धारा देता है। संधारित्र से लगे फ़िल्टर परिपथ से धारा चिकनी बनाई जाती है।"),
C("🔆","विशेष डायोड",["ज़ेनर डायोड: वोल्टेज नियंत्रक","प्रकाश उत्सर्जक डायोड","फ़ोटो डायोड","सौर सेल"],"कुछ डायोड विशेष काम के होते हैं। ज़ेनर डायोड वोल्टेज को स्थिर रखने के लिए काम आता है। प्रकाश उत्सर्जक डायोड, यानी एल.ई.डी., विद्युत ऊर्जा को सीधे प्रकाश में बदलता है और घर की लाइट में काम आता है। फ़ोटो डायोड प्रकाश को पहचानता है और सौर सेल प्रकाश से बिजली बनाता है।"),
],5)
